/// An 80-word block of `SplitMix64`'s output from `seed`, two words from each of its 40
/// values, low half first, as `unit_pub`'s witnesses are made.
fn seeded(seed: u64) -> [u32; 80] {
    let mut state = seed;
    let mut w = [0; 80];
    for pair in w.as_chunks_mut::<2>().0 {
        state = state.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = state;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^= z >> 31;
        pair[0] = u32::try_from(z & 0xFFFF_FFFF).unwrap();
        pair[1] = u32::try_from(z >> 32).unwrap();
    }
    w
}

/// For each vector, by its bit, a seed whose block [`seeded`] gives selects it.
const WITNESS_SEEDS: [u64; 32] = [
    1016, 2073, 8279, 283, 289, 13141, 11, 562, 125, 23, 185, 4382, 216, 19083, 356, 169,
    201, 912, 37, 18885, 17678, 15423, 348, 8928, 729, 5478, 159, 45875, 32064, 596,
    32134, 5137,
];

/// The export returns the native mask: of uniform blocks and of the table's differences
/// taken as blocks, which select nothing, and of a block selecting each vector, so that
/// every bit of the mask it writes is one the native check set.
#[test]
fn ubc_check_writes_the_native_mask() {
    let mut blocks = vec![[0; 80], [u32::MAX; 80]];
    blocks.extend(DVS.iter().map(|r| *r.as_ref().message_difference()));
    blocks.extend(WITNESS_SEEDS.map(seeded));
    let mut selected = 0;
    for block in &blocks {
        let mask = exported(block);
        assert_eq!(mask, super::super::ubc_check(block));
        selected |= mask[0];
    }
    assert_eq!(selected, u32::MAX);
}

