/// Replaces `mac::DVMASKSIZE`
pub const DVMASKSIZE: usize = 1;

/// The bit of [`ubc_check`]'s mask that selects the disturbance vector `I(43,0)`, the
/// record of [`SHA1_DVS`] whose [`mask_bit`](DvInfoRef::mask_bit) is 0.
