    // no thread affinity, nothing to release, so moving one to another thread moves bytes.
    unsafe impl Send for DvInfo {}

    // SAFETY: `DvInfoMut` is an exclusive borrow of such a value, as `&mut DvInfo`.
    unsafe impl Send for DvInfoMut<'_> {}

    // SAFETY: shared access only reads the fields (no handle writes one: `DvInfoMut` has no
    // setter, and C writes no record of the table it reads), so concurrent readers race
    // nothing.
    unsafe impl Sync for DvInfo {}

    // SAFETY: as above; `DvInfoRef` is a shared borrow, as `&DvInfo`.
    unsafe impl Send for DvInfoRef<'_> {}

    // SAFETY: as above.
    unsafe impl Sync for DvInfoRef<'_> {}

    // SAFETY: `&DvInfoMut` only reaches the getters, through `as_ref`.
    unsafe impl Sync for DvInfoMut<'_> {}

    impl DvInfo {
        /// Builds the record of a disturbance vector: its type (`1` for I, `2` for II, `0`
        /// for the record that ends the table) and parameters `k` and `b`, the step to
        /// recompress from, the word and bit of `ubc_check`'s mask that select it, and the
        /// expanded message block's XOR difference it defines.
        ///
        /// Returns `None` where `sha1.c` could not read the record: a step outside `0..80`,
        /// which indexes its saved states, a bit outside `0..32`, by which it shifts the mask,
        /// or a word other than `0`, the one word of `ubc_check`'s mask (`DVMASKSIZE` is 1).
        /// The other fields take any value. `const`, so that a table of records is a
        /// `static`.
        ///
        /// Not every step in range is one `sha1.c` recompresses from: it saves the states of
        /// the steps `ubc_check.h` names (`DOSTORESTATE58` and `DOSTORESTATE65`), and its
        /// `sha1_recompression_step` aborts the process on any other. A table `sha1.c` reads
        /// holds those steps alone, as `sha1_dvs`'s records do.
        #[must_use]
        pub const fn new(
            dv_type: i32,
            k: i32,
            b: i32,
            recompression_step: i32,
            mask_word: i32,
            mask_bit: i32,
            message_difference: [u32; STEPS],
        ) -> Option<Self> {
            #[expect(
                clippy::cast_possible_truncation,
                clippy::cast_possible_wrap,
                reason = "`STEPS` is 80, and `u32::BITS` 32: both fit in an `i32`"
            )]
            let in_range = 0 <= recompression_step
                && recompression_step < STEPS as i32
                && mask_word == 0
                && 0 <= mask_bit
                && mask_bit < u32::BITS as i32;
            if !in_range {
                return None;
            }
            Some(Self(
                sys::dv_info_t {
                    dvType: dv_type,
                    dvK: k,
                    dvB: b,
                    testt: recompression_step,
                    maski: mask_word,
                    maskb: mask_bit,
                    dm: message_difference,
                },
                PhantomData,
            ))
        }
    }

    impl<'a> DvInfoRef<'a> {
        /// The vector's type: `1` for a type I vector, `2` for a type II, and `0` for the
        /// record that ends the table, as `sha1.c` reads it.
        ///
        /// Wraps `fld::dv_info_t.dvType`
        #[doc(alias = "dv_info_t.dvType")]
        #[must_use]
        pub fn dv_type(&self) -> i32 {
            // SAFETY: `self.as_ptr()` addresses the live record this handle borrows; the
            // projection forms no reference to it.
            let dv_type_ptr = unsafe { &raw const (*self.as_ptr()).dvType };
            // SAFETY: an initialised `c_int`, unwritten while the handle borrows it.
            unsafe { dv_type_ptr.read() }
        }

        /// The step `sha1.c` recompresses from, in `0..80`: the index of the state it saved
        /// at that step, which it saves only for the steps `ubc_check.h` names, 58 and 65.
        ///
        /// # Panics
        ///
        /// Panics, with `dv_info_t.testt out of range`, only if a record that
        /// [`CRefSeam::from_ptr`] borrowed breaks its contract.
        ///
        /// Wraps `fld::dv_info_t.testt`
        #[doc(alias = "dv_info_t.testt")]
        #[must_use]
        pub fn recompression_step(&self) -> usize {
            // SAFETY: `self.as_ptr()` addresses the live record this handle borrows; the
            // projection forms no reference to it.
            let testt_ptr = unsafe { &raw const (*self.as_ptr()).testt };
            // SAFETY: an initialised `c_int`, unwritten while the handle borrows it.
            let testt = unsafe { testt_ptr.read() };
            usize::try_from(testt)
                .ok()
                .filter(|&step| step < STEPS)
                .expect("dv_info_t.testt out of range")
        }

        /// The bit of `ubc_check`'s one-word mask that selects this vector, in `0..32`.
        ///
        /// # Panics
        ///
        /// Panics, with `dv_info_t.maskb out of range`, only if a record that
        /// [`CRefSeam::from_ptr`] borrowed breaks its contract.
        ///
        /// Wraps `fld::dv_info_t.maskb`
        #[doc(alias = "dv_info_t.maskb")]
        #[must_use]
        pub fn mask_bit(&self) -> u32 {
            // SAFETY: `self.as_ptr()` addresses the live record this handle borrows; the
            // projection forms no reference to it.
            let maskb_ptr = unsafe { &raw const (*self.as_ptr()).maskb };
            // SAFETY: an initialised `c_int`, unwritten while the handle borrows it.
            let maskb = unsafe { maskb_ptr.read() };
            u32::try_from(maskb)
                .ok()
                .filter(|&bit| bit < u32::BITS)
                .expect("dv_info_t.maskb out of range")
        }

        /// The XOR difference the vector defines on an expanded message block: one word per
        /// step, which `sha1.c` XORs into the block before it recompresses.
        ///
        /// Wraps `fld::dv_info_t.dm`
        #[doc(alias = "dv_info_t.dm")]
        #[must_use]
        pub fn message_difference(&self) -> &'a [u32; STEPS] {
            // SAFETY: `self.as_ptr()` addresses the live record this handle borrows; the
            // projection forms no reference to it.
            let dm_ptr = unsafe { &raw const (*self.as_ptr()).dm };
            // SAFETY: `dm_ptr` addresses the record's 80 initialised, aligned `u32`s, which
            // live as long as the record this handle borrows for `'a`; nothing writes them
            // while it does: `DvInfoMut` has no setter, a shared handle taken from one
            // borrows it, and C writes no record of the table it reads.
            unsafe { &*dm_ptr }
        }

        /// A copy of the record, which outlives the borrow.
        #[must_use]
        pub fn copied(&self) -> DvInfo {
            // SAFETY: `self.as_ptr()` addresses the live, initialised record this handle
            // borrows, unwritten while it does; it is plain data, so a bitwise copy is a
            // value of its own.
            DvInfo(unsafe { self.as_ptr().read() }, PhantomData)
        }
    }

    impl PartialEq for DvInfo {
        /// Every field equal, those [`DvInfoRef`]'s getters leave out included.
        fn eq(&self, other: &Self) -> bool {
            let (a, b) = (&self.0, &other.0);
            (a.dvType, a.dvK, a.dvB, a.testt, a.maski, a.maskb, a.dm)
                == (b.dvType, b.dvK, b.dvB, b.testt, b.maski, b.maskb, b.dm)
        }
    }

    impl Eq for DvInfo {}

    impl PartialEq for DvInfoRef<'_> {
        fn eq(&self, other: &Self) -> bool {
            self.copied() == other.copied()
        }
    }

    impl Eq for DvInfoRef<'_> {}

    impl fmt::Debug for DvInfo {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            let r = &self.0;
            f.debug_struct("DvInfo")
                .field("dv_type", &r.dvType)
                .field("k", &r.dvK)
                .field("b", &r.dvB)
                .field("recompression_step", &r.testt)
                .field("mask_word", &r.maski)
                .field("mask_bit", &r.maskb)
                .field("message_difference", &r.dm)
                .finish()
        }
    }

    impl fmt::Debug for DvInfoRef<'_> {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            self.copied().fmt(f)
        }
    }

    impl fmt::Debug for DvInfoMut<'_> {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            self.as_ref().fmt(f)
        }
    }
}

/// `dv`, which the compiler alone runs to build the table, run at run time: it builds the
/// records the table holds, and refuses one `sha1.c` could not read, as the build would.
#[cfg(test)]
mod unit_priv {
    use super::{DVS, STEPS, dv};

    #[test]
    fn dv_builds_the_records_of_the_table() {
        let first = dv(1, 43, 0, 58, 0, 0, DVS[0].as_ref().message_difference());
        assert_eq!(first, DVS[0]);
        assert_eq!(dv(0, 0, 0, 0, 0, 0, &[0; STEPS]), DVS[32]);
    }

    #[test]
    #[should_panic(expected = "a record of sha1_dvs is out of the range sha1.c reads")]
    fn dv_refuses_a_record_sha1_c_cannot_read() {
        let _ = dv(1, 43, 0, 80, 0, 0, &[0; STEPS]);
    }
}

/// The gateway through which `sha1.c`'s C reaches the module once it has switched: the table
/// `sha1_dvs` it reads and `ubc_check`, which it calls with the block it expanded.
#[cfg(feature = "ffi-export-src-util-hash-sha1dc-ubc-check-c")]
#[expect(
    unsafe_code,
    reason = "exports `sha1_dvs` and `ubc_check` under their C names, and reads and writes \
              through the pointers C passes"
)]
mod ffi_export {
    use core::marker::PhantomData;

    use ffibox::CCell;
    use ffibox::callback::barrier;

    use super::{DV_COUNT, DVMASKSIZE, DVS, DvInfo, STEPS};
    use crate::sys::libgit2 as sys;

    // The export has its raw binding's type: the array's elements coerce to one function
    // pointer type only when their signatures agree.
    const _: () = {
        let _ = [sys::ubc_check, ubc_check];
    };

    /// The element type of the array a pointer addresses.
    const fn element<T, const N: usize>(_: *const [T; N]) -> PhantomData<T> {
        PhantomData
    }

    // The table's elements have the layout of its raw binding's, `dv_info_t`, which `DvInfo`
    // is transparent over: the closure is type-checked, never called.
    const _: fn() = || {
        let _: PhantomData<<DvInfo as CCell>::C> = element(&raw const sys::sha1_dvs);
    };

    /// The disturbance vectors SHA-1 collision detection checks, the storage of
    /// [`SHA1_DVS`](super::SHA1_DVS), which re-exports it: `ubc_check.c`'s `sha1_dvs`, under
    /// its C name, which `sha1.c`'s `sha1_process` reads, as `extern dv_info_t sha1_dvs[]`, up
    /// to its record whose type is `0`. Immutable: no C writes it.
    ///
    /// Replaces `glb::sha1_dvs`
    #[unsafe(no_mangle)]
    pub static sha1_dvs: [DvInfo; DV_COUNT] = DVS;

    /// `ubc_check`: [`super::ubc_check`] of the 80 words at `w`, its mask written through
    /// `dvmask`. It cannot fail, so a panic aborts.
    ///
    /// # Safety
    ///
    /// `w` is valid and aligned for reads of 80 initialised `uint32_t`s, which nothing writes
    /// during the call, and `dvmask` valid and aligned for a write of `DVMASKSIZE` (1)
    /// `uint32_t`s, as `sha1_process` passes its expanded block, `ctx->m1`, which
    /// `sha1_compression_states` has written whole, and its local `ubc_dv_mask`.
    #[unsafe(no_mangle)]
    unsafe extern "C" fn ubc_check(w: *const u32, dvmask: *mut u32) {
        // SAFETY: the caller guarantees that `w` addresses 80 initialised, aligned `u32`s,
        // which nothing writes while the reference lives, the call; `[u32; 80]` has their
        // layout.
        let w = unsafe { &*w.cast::<[u32; STEPS]>() };
        let mask = barrier(|| super::ubc_check(w), || std::process::abort());
        // SAFETY: the caller guarantees that `dvmask` is valid and aligned for a write of
        // `DVMASKSIZE` `u32`s, which `[u32; DVMASKSIZE]` has the layout of.
        unsafe { dvmask.cast::<[u32; DVMASKSIZE]>().write(mask) };
    }

    /// The exports as `sha1_process` reaches them: the table it reads, and `ubc_check` of a
    /// block held in an allocation of exactly 80 words, its mask written over one of exactly
    /// `DVMASKSIZE`, so that Miri reports a read or a write past them. They compile with the
    /// gateway.
    #[cfg(test)]
    mod unit_priv {
        use core::ptr;

        use super::{sha1_dvs, ubc_check};
        use crate::libgit2::src::util::hash::sha1dc::ubc_check::{DVMASKSIZE, DVS, SHA1_DVS};

        /// The export of `block`, through exact allocations; the mask slot starts at
        /// `u32::MAX`, as `sha1_process`'s does.
        fn exported(block: &[u32; 80]) -> [u32; DVMASKSIZE] {
            let w: Box<[u32]> = block.as_slice().into();
            let mut mask: Box<[u32]> = vec![u32::MAX; DVMASKSIZE].into_boxed_slice();
            // SAFETY: `w` holds 80 initialised words, which nothing writes during the call, and
            // `mask` `DVMASKSIZE` words, both aligned.
            unsafe { ubc_check(w.as_ptr(), mask.as_mut_ptr()) };
            mask.as_ref().try_into().unwrap()
        }

        /// The export returns the native mask: of uniform blocks, which select nothing, and of
        /// the table's differences taken as blocks.
        #[test]
        fn ubc_check_writes_the_native_mask() {
            let mut blocks = vec![[0; 80], [u32::MAX; 80]];
            blocks.extend(DVS.iter().map(|r| *r.as_ref().message_difference()));
            for block in &blocks {
                assert_eq!(exported(block), super::super::ubc_check(block));
            }
        }

        /// `sha1_dvs` is the storage `SHA1_DVS` names, one table, with every record of `DVS`.
        #[test]
        fn sha1_dvs_is_the_one_table() {
            assert!(ptr::eq(&raw const sha1_dvs, &raw const SHA1_DVS));
            assert!(sha1_dvs.iter().eq(DVS.iter()));
            assert_eq!(sha1_dvs[32].as_ref().dv_type(), 0);
        }
    }
}

