//! `src/util/hash/sha1dc/ubc_check.c`: the unavoidable-bitcondition check of SHA-1 collision
//! detection, ported to Rust.
//!
//! # Disturbance vectors
//!
//! SHA-1 collision detection (`sha1.c`) checks each message block against a table of
//! disturbance vectors, `sha1_dvs`: one [`DvInfo`] record per vector, of type I or II
//! ([`dv_type`](DvInfoRef::dv_type)), ended by a record whose type is `0`. For a record whose
//! bit `ubc_check` sets in its mask ([`mask_bit`](DvInfoRef::mask_bit)), `sha1.c` XORs the
//! expanded message block with the vector's message difference
//! ([`message_difference`](DvInfoRef::message_difference)) and recompresses it from the
//! record's step ([`recompression_step`](DvInfoRef::recompression_step)), with the state it
//! saved at that step.
//!
//! The record keeps the C layout, `dv_info_t`, while `sha1.c`'s C reads the table: its
//! `sha1_process` indexes the saved states by the step and shifts a mask by the bit, both
//! unchecked, so [`DvInfo::new`] builds only records whose step and bit are in range.
//!
//! # The check
//!
//! The table is [`SHA1_DVS`], and [`ubc_check`] the check that selects its vectors: of an
//! expanded message block, the mask of the vectors whose unavoidable bitconditions it meets,
//! each by its `DV_*_BIT` constant. Both are native Rust, and the record's C layout is all
//! the module keeps of C. `sha1.c` stays C until its own port, so the module's gateway exports
//! them under their C names, `sha1_dvs` and `ubc_check`, compiled only under the export
//! feature `ffi-export-src-util-hash-sha1dc-ubc-check-c` until the module switches from C:
//! the table's storage is then the export's, which [`SHA1_DVS`] names.

pub use self::ffi_import::{DvInfo, DvInfoMut, DvInfoRef};

/// The steps of SHA-1's compression, and the words of an expanded message block.
const STEPS: usize = 80;

/// The words of the mask [`ubc_check`] returns: one, whose 32 bits select the 32 disturbance
/// vectors of [`SHA1_DVS`].
///
/// Replaces `mac::DVMASKSIZE`
pub const DVMASKSIZE: usize = 1;

/// The bit of [`ubc_check`]'s mask that selects the disturbance vector `I(43,0)`, the
/// record of [`SHA1_DVS`] whose [`mask_bit`](DvInfoRef::mask_bit) is 0.
///
/// Replaces `glb::DV_I_43_0_bit`
#[doc(alias = "DV_I_43_0_bit")]
pub const DV_I_43_0_BIT: u32 = 1;

/// The bit of [`ubc_check`]'s mask that selects the disturbance vector `I(44,0)`, the
/// record of [`SHA1_DVS`] whose [`mask_bit`](DvInfoRef::mask_bit) is 1.
///
/// Replaces `glb::DV_I_44_0_bit`
#[doc(alias = "DV_I_44_0_bit")]
pub const DV_I_44_0_BIT: u32 = 1 << 1;

/// The bit of [`ubc_check`]'s mask that selects the disturbance vector `I(45,0)`, the
/// record of [`SHA1_DVS`] whose [`mask_bit`](DvInfoRef::mask_bit) is 2.
///
/// Replaces `glb::DV_I_45_0_bit`
#[doc(alias = "DV_I_45_0_bit")]
